"""Personal mailbox scope, row locks and provider dispatch shared by email routes."""

from __future__ import annotations

import uuid

from fastapi import HTTPException, status
from sqlalchemy import select, true
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import InstrumentedAttribute, undefer
from sqlalchemy.sql.elements import ColumnElement

from app.application.interfaces.email_provider import EmailProvider
from app.application.security.authorization_policy import AuthorizationPolicy
from app.application.security.email_scope import (
    EmailScopeError,
    email_agency_scope,
    email_owner_filters,
)
from app.application.use_cases.email_integrations import overview
from app.core.config.settings import Settings
from app.core.logging.logger import get_logger
from app.domain.entities.entities import User, UserRole
from app.infrastructure.database.email_models import EmailConnectionModel
from app.infrastructure.database.models import AgencyModel
from app.infrastructure.email.gmail_provider import GmailEmailProvider
from app.infrastructure.email.outlook_provider import OutlookEmailProvider
from app.presentation.dependencies.auth import require_role

logger = get_logger(__name__)

EMAIL_INTEGRATION_ROLES = [
    UserRole.SUPER_ADMIN,
    UserRole.AGENCY_ADMIN,
    UserRole.AGENCY_MANAGER,
    UserRole.AGENCY_STAFF,
]
_current_email_user = require_role(EMAIL_INTEGRATION_ROLES)
_ACTIVE_CONNECTION_STATUSES = overview.ACTIVE_CONNECTION_STATUSES
_ACTIVE_REVIEW_STATUSES = overview.ACTIVE_REVIEW_STATUSES


def _provider_instance(provider: str, settings: Settings) -> EmailProvider:
    if provider == "gmail":
        return GmailEmailProvider(settings=settings)
    if provider == "outlook":
        return OutlookEmailProvider(settings=settings)
    raise HTTPException(
        status_code=status.HTTP_400_BAD_REQUEST,
        detail="This email provider is not supported.",
    )


def _agency_scope(user: User) -> uuid.UUID | None:
    try:
        return email_agency_scope(user)
    except EmailScopeError as exc:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=str(exc)) from exc


def _email_owner_filters(
    owner_column: InstrumentedAttribute[uuid.UUID],
    agency_column: InstrumentedAttribute[uuid.UUID],
    user: User,
) -> tuple[ColumnElement[bool], ...]:
    """Return the immutable personal mailbox boundary for an authenticated user."""

    _agency_scope(user)  # Preserve the website's HTTP error contract.
    return email_owner_filters(owner_column, agency_column, user)


def _group_role_visibility_filter(user: User) -> ColumnElement[bool]:
    if user.role == UserRole.AGENCY_STAFF:
        return AuthorizationPolicy.staff_group_visibility_filter(user)
    return true()


def _passport_role_visibility_filter(user: User) -> ColumnElement[bool]:
    if user.role == UserRole.AGENCY_STAFF:
        return AuthorizationPolicy.staff_passport_visibility_filter(user)
    return true()


def _require_provider_account_owner(
    connection: EmailConnectionModel | None,
    *,
    agency_id: uuid.UUID,
    owner_user_id: uuid.UUID,
) -> None:
    """Reject reconnecting a provider identity owned by another dashboard user."""

    if connection is not None and (
        connection.agency_id != agency_id or connection.owner_user_id != owner_user_id
    ):
        raise ValueError("Provider account already belongs to another owner")


async def _default_organization_agency_id(session: AsyncSession, user: User) -> uuid.UUID:
    if user.agency_id is not None:
        return user.agency_id
    agency_id = await session.scalar(
        select(AgencyModel.id)
        .where(AgencyModel.is_active.is_(True))
        .order_by(AgencyModel.created_at.asc(), AgencyModel.id.asc())
        .limit(1)
    )
    if agency_id is None:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Create the organization before connecting an email account.",
        )
    return agency_id


async def _owned_connection(
    session: AsyncSession,
    *,
    connection_id: uuid.UUID,
    owner_user_id: uuid.UUID,
    agency_id: uuid.UUID | None,
    for_update: bool = False,
    with_tokens: bool = False,
) -> EmailConnectionModel:
    stmt = select(EmailConnectionModel).where(
        EmailConnectionModel.id == connection_id,
        EmailConnectionModel.owner_user_id == owner_user_id,
    )
    if agency_id is not None:
        stmt = stmt.where(EmailConnectionModel.agency_id == agency_id)
    if with_tokens:
        stmt = stmt.options(
            undefer(EmailConnectionModel.access_token_ciphertext),
            undefer(EmailConnectionModel.refresh_token_ciphertext),
        )
    if for_update:
        stmt = stmt.with_for_update()
    connection = await session.scalar(stmt)
    if connection is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Email connection was not found.",
        )
    return connection


def _enqueue_connection_sync(
    connection: EmailConnectionModel,
    *,
    provider_message_id: str | None = None,
) -> bool:
    try:
        from app.infrastructure.email.tasks import sync_email_connection

        task_kwargs = {
            "connection_id": str(connection.id),
            "agency_id": str(connection.agency_id),
            "owner_user_id": str(connection.owner_user_id),
            "provider_account_id": connection.provider_account_id,
            "sync_generation": connection.sync_generation,
        }
        if provider_message_id:
            task_kwargs["provider_message_id"] = provider_message_id
        sync_email_connection.apply_async(
            kwargs=task_kwargs,
            queue="email_integrations",
        )
        return True
    except Exception as exc:
        logger.warning(
            "email_sync_enqueue_failed",
            connection_id=str(connection.id),
            error_type=type(exc).__name__,
        )
        return False

"""Shared credential revocation protocol; callers retain transaction ownership."""

from __future__ import annotations

from datetime import datetime

from app.application.interfaces.email_provider import EmailProvider, EmailProviderError
from app.infrastructure.database.email_models import EmailConnectionModel
from app.infrastructure.email.token_encryption import (
    EmailTokenCipher,
    EncryptedToken,
    TokenEncryptionError,
)


def revocation_credential(
    connection: EmailConnectionModel,
    provider: EmailProvider,
) -> tuple[str | None, bool]:
    if not provider.supports_remote_token_revocation:
        return None, False
    try:
        cipher = EmailTokenCipher.from_settings()
        ciphertext = connection.refresh_token_ciphertext or connection.access_token_ciphertext
        token = (
            cipher.decrypt(
                EncryptedToken(
                    ciphertext=ciphertext.decode("ascii"),
                    key_version=connection.token_key_version,
                )
            )
            if ciphertext
            else None
        )
        return token, False
    except (TokenEncryptionError, UnicodeDecodeError):
        return None, True


def fence_connection_sync(connection: EmailConnectionModel, now: datetime) -> None:
    """Invalidate old worker claims before a caller commits and contacts a provider."""
    connection.status = "disconnecting"
    connection.sync_state = "blocked"
    connection.sync_generation += 1
    connection.sync_lease_token = None
    connection.sync_lease_expires_at = None
    connection.next_sync_at = None
    connection.updated_at = now


async def revoke_provider_credential(
    provider: EmailProvider,
    token: str | None,
    decryption_failed: bool,
) -> EmailProviderError | None:
    if decryption_failed:
        return EmailProviderError(
            "Stored email credentials could not be opened",
            code="EMAIL_TOKEN_DECRYPTION_FAILED",
        )
    if token:
        try:
            await provider.revoke_token(token=token)
        except EmailProviderError as error:
            # Already-invalid tokens are safe to forget; unknown outcomes are not.
            if error.status_code not in {400, 401, 404}:
                return error
    return None

"""OAuth return and connection-action policy helpers for email integrations."""

from __future__ import annotations

from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

from fastapi import HTTPException, status

from app.application.use_cases.email_integrations.overview import provider_configured, secret_is_set
from app.core.config.settings import Settings
from app.infrastructure.database.email_models import EmailConnectionModel


def _provider_configured(settings: Settings, provider: str = "gmail") -> bool:
    return provider_configured(settings, provider)


def _provider_scopes(provider: str) -> list[str]:
    if provider == "outlook":
        return [
            "openid",
            "profile",
            "offline_access",
            "https://graph.microsoft.com/User.Read",
            "https://graph.microsoft.com/Mail.Read",
        ]
    return ["https://www.googleapis.com/auth/gmail.readonly"]


def _secret_is_set(value: object) -> bool:
    return secret_is_set(value)


def _require_feature(settings: Settings) -> None:
    if not settings.email_integrations_enabled:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="Email integrations are not enabled for this deployment.",
        )


def _oauth_return_url(settings: Settings, outcome: str, provider: str = "gmail") -> str:
    allowed = {"connected", "reconnected", "cancelled", "denied", "failed"}
    safe_outcome = outcome if outcome in allowed else "failed"
    parsed = urlsplit(settings.email_oauth_frontend_return_url)
    query = [
        (key, value)
        for key, value in parse_qsl(parsed.query, keep_blank_values=True)
        if key not in {"code", "state", "error", "email_oauth", "email_provider"}
    ]
    query.append(("email_oauth", safe_outcome))
    query.append(("email_provider", provider if provider in {"gmail", "outlook"} else "gmail"))
    return urlunsplit((parsed.scheme, parsed.netloc, parsed.path, urlencode(query), ""))


def _allowed_connection_actions(
    connection: EmailConnectionModel,
    settings: Settings,
) -> list[str]:
    reconnect_available = settings.email_integrations_enabled and _provider_configured(
        settings,
        connection.provider,
    )
    sync_available = settings.email_integrations_enabled and settings.email_sync_enabled
    if connection.status == "paused":
        actions = ["resume"] if sync_available else []
        if reconnect_available:
            actions.append("reconnect")
        actions.extend(["disconnect", "remove"])
        return actions
    if connection.status in {"expired", "disconnected"}:
        actions = ["reconnect"] if reconnect_available else []
        actions.extend(["disconnect", "remove"])
        return actions
    if connection.status == "disconnecting":
        return ["disconnect", "remove"]
    actions = ["sync"] if sync_available else []
    actions.append("pause")
    if reconnect_available:
        actions.append("reconnect")
    actions.extend(["disconnect", "remove"])
    return actions


def _email_removal_confirmation_matches(
    *,
    confirmation_email: str,
    connection_email: str,
) -> bool:
    """Require the operator to type the exact selected mailbox address."""

    return confirmation_email.strip().casefold() == connection_email.strip().casefold()
